import{_ as i,o as s,c as a,a3 as r,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const l="/bilder/schueler/akt-halbj-allgemein-1.png",h="/bilder/schueler/akt-halbj-allgemein-4.png",d="/bilder/schueler/akt-halbj-allgemeine-angaben-ii.png",u="/bilder/schueler/akt-halbj-allgemein-7.png",o="/bilder/schueler/akt-halbj-allgemein-2.png",c="/bilder/schueler/akt-halbj-allgemein-3.png",g="/bilder/schueler/akt-halbj-allgemein-9.png",b="/bilder/schueler/akt-halbj-allgemein-8.png",z=JSON.parse('{"title":"Lernabschnitte und aktuelle Laufbahndaten verwalten","description":"","frontmatter":{"title":"Lernabschnitte und aktuelle Laufbahndaten verwalten","source_pageid":503,"source_revision":5662},"headers":[],"relativePath":"schild3/schueler/aktuelles-halbjahr-aktueller-abschnitt-schueler.md","filePath":"schild3/schueler/aktuelles-halbjahr-aktueller-abschnitt-schueler.md"}'),m={name:"schild3/schueler/aktuelles-halbjahr-aktueller-abschnitt-schueler.md"};function p(f,t,k,w,A,S){return s(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="lernabschnitte-und-aktuelle-laufbahndaten-verwalten" tabindex="-1">Lernabschnitte und aktuelle Laufbahndaten verwalten <a class="header-anchor" href="#lernabschnitte-und-aktuelle-laufbahndaten-verwalten" aria-label="Permalink to &quot;Lernabschnitte und aktuelle Laufbahndaten verwalten&quot;">​</a></h1><p>Wählen Sie einen Lernabschnitt und prüfen Sie die zugehörigen Laufbahndaten. Die Übersicht führt Schuljahr, Abschnitt, Jahrgang und Klasse sowie Wertung und Wiederholung zusammen.</p><h2 id="lernabschnittsubersicht" tabindex="-1">Lernabschnittsübersicht <a class="header-anchor" href="#lernabschnittsubersicht" aria-label="Permalink to &quot;Lernabschnittsübersicht&quot;">​</a></h2><p><a href="/bilder/schueler/akt-halbj-allgemein-1.png"><img src="'+l+'" alt="Abschnitte und allgemeine Angaben zu einen Lernenden." loading="lazy"></a></p><p><em>Abschnitte und allgemeine Angaben zu einen Lernenden.</em></p><p>Ein <strong>Lernabschnitt</strong> ist ein Schulhalbjahr oder Quartal. Unter <strong>Schüler → Akt. Halbjahr</strong> sehen Sie die vorhandenen Lernabschnitte der Person, die links in der Namensliste ausgewählt ist.</p><p>Wählen Sie in der Lernabschnittsliste einen Eintrag aus. Unter <strong>Allgemeine Angaben</strong> erscheinen die Daten dieses Abschnitts.</p><p>Lernabschnitte werden üblicherweise bei der Neuaufnahme, bei der Versetzung oder über den vorbereitenden Gruppenprozess angelegt. Bei Bedarf legen Sie einen Abschnitt mit <strong>+</strong> von Hand an und speichern ihn mit dem kleinen Haken.</p><p>Die Lernabschnitte führen jeweils das Schuljahr und den Abschnitt, also Halbjahre oder Quartale, den Jahrgang und die Klasse auf.</p><p>Die Liste zeigt auch, ob ein Abschnitt <strong>gewertet</strong> wird und ob er eine <strong>Wiederholung</strong> ist. Ändern Sie diese Angaben unter <strong>Allgemeine Angaben</strong> des gewählten Abschnitts; direkt in der Übersichtstabelle sind sie nicht bearbeitbar.</p>',10),e("div",{"data-hint-kind":"example",class:"example custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"example","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 3h6m-5 0v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3M7 15h10"})]),n("Beispiel")]),e("p",null,[n("Wiederholt jemand in der gymnasialen Oberstufe z.B. die Q1, würde der alte Durchlauf durch Entfernung des Hakens als "),e("em",null,"nicht gewertet"),n(" markiert werden und bei dem Abschnitt für die neue Q1.1 würde dieser als "),e("em",null,'"gewertet"'),n(" und "),e("em",null,'"wiederh."'),n(" markiert werden.")])],-1),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,"Tipp 1: Bei einer Neuaufnahme können Sie frühere Lernabschnitte der zuvor besuchten Schule von Hand ergänzen. So lassen sich auch deren Noten erfassen. Das ist zum Beispiel für Epochalfächer oder die Sprachenfolge hilfreich."),e("p",null,[n("Tipp 2: Wenn Zeugnisse oder andere Leistungsdaten aus einem Abschnitt gedruckt werden sollen, etwa um noch Noten eines wiederholten Lernabschnitts auszugeben, muss der Haken "),e("em",null,'"gewertet"'),n(" gesetzt sein, damit Noten erscheinen. Der Haken kann nach dem Druck dann wieder entfernt werden.")])],-1),r('<h3 id="allgemeine-angaben" tabindex="-1">Allgemeine Angaben <a class="header-anchor" href="#allgemeine-angaben" aria-label="Permalink to &quot;Allgemeine Angaben&quot;">​</a></h3><p><a href="/bilder/schueler/akt-halbj-allgemein-4.png"><img src="'+h+'" alt="Soll eine neue Adresse angelegt werden, ist die über das Feld Neueintrag unten möglich.Allgemeine Angaben zu einem Lernabschnitt." loading="lazy"></a></p><p><em>Soll eine neue Adresse angelegt werden, ist die über das Feld <strong>Neueintrag</strong> unten möglich.Allgemeine Angaben zu einem Lernabschnitt.</em></p><p>Als erste Zeile in Bereich <em>&quot;Allgemeine Angaben&quot;</em> wird angezeigt, ob es sich um einen gewerteten Abschnitt handelt oder nicht.</p><p>Zusätzlich wird mit &quot;<strong>2. Durchgang (oder höher)</strong>&quot; angegeben, ob es sich um eine Wiederholung handelt.</p>',5),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Für einen regulären Lernabschnitt setzen Sie "),e("strong",null,"gewertet"),n(". Bei der ersten Wiederholung gilt:")]),e("ul",null,[e("li",null,[n("Im ursprünglichen Abschnitt entfernen Sie "),e("strong",null,"gewertet"),n(". "),e("strong",null,"Keine Wiederholung"),n(" bleibt dort bestehen.")]),e("li",null,[n("Im neuen Durchgang setzen Sie "),e("strong",null,"gewertet"),n(" und "),e("strong",null,"2. Durchgang (oder höher)"),n(".")])]),e("p",null,"So bleibt der ursprüngliche Durchgang gespeichert, wird aber nicht mehr gewertet."),e("p",null,[n("Wird der Lernabschnitt noch einmal wiederholt, wäre der neue Abschnitt mit beiden Haken gekennzeichnet, der vorherige Abschnitt würde auf "),e("em",null,"nicht gewertet"),n(" geändert, bliebe aber nach wie vor ein "),e("em",null,"2. Durchgang (oder höher)"),n(".")])],-1),r('<p>Die allgemeinen Angaben enthalten <strong>Schuljahr</strong>, <strong>Abschnitt</strong>, <strong>Klasse</strong> und <strong>Jahrgang</strong>. Ein Abschnitt ist ein Halbjahr oder Quartal. <strong>Datum von</strong> und <strong>Datum bis</strong> geben Beginn und Ende des Lernabschnitts an.</p><p>In der Grundschule wird bei Schülerinnen und Schülern der <strong>Jahrgänge 01 und 02</strong> zusätzlich das <strong>EP-Jahr E1, E2 oder E3</strong> zugeordnet. Es beschreibt, im wievielten Schuljahr sich das Kind innerhalb dieser beiden Jahrgänge befindet. Die Zuordnung erfolgt hier <strong>in jedem Halbjahr</strong>.</p><p>Das momentane EP-Jahr wird zusätzlich in der <strong>Schülertabelle</strong> gespeichert und unter <strong>Individualdaten I</strong> angezeigt. In den Jahrgängen 01 und 02 ist es dort <strong>nicht editierbar</strong>. Ab <strong>Jahrgang 03</strong> entfällt hier unter den allgemeinen Angaben die Eingabemöglichkeit; der gespeicherte Wert kann dann in <strong>Individualdaten I</strong> korrigiert werden. Weitere Hinweise stehen unter <a href="/schild3/schueler/eintragung-der-ep-jahre-tutorial.html">Die Jahre der Schuleingangsphase eintragen</a>.</p><p>Klassenangaben und <strong>Klassenleitung</strong> werden üblicherweise aus der <em>Klassen-/Versetzungstabelle</em> beziehungsweise beim Abschnittswechsel übernommen. Die Zuordnung des <strong>EP-Jahres</strong> ist zusätzlich in jedem Halbjahr zu prüfen; sie lässt sich nicht allein aus der Klasse ableiten.</p><p>Zusätzlich zur Klassenleitung lassen sich Personen bei <strong>Sonderpädagoge</strong> und <strong>Tutor</strong> erfassen.</p><p>Ebenso werden im Regelfall automatisch gesetzt: die <strong>Schulgliederung</strong>, <strong>Prüfungsordnung</strong>, <strong>Klassenorganisationsform</strong> oder die <strong>Klassenart</strong>.</p><p>Unter den Fehlstunden werden die Felder angewählt, mit denen <strong>Schwerstbehinderung</strong>, <strong>Autismus</strong>, <strong>Zieldifferentes Lernen</strong> und <strong>AO-SF</strong> erfasst werden.</p><p>Ist die Anschlussperspektive nach dem Schulabschluss oder Abgang noch ungeklärt, können Sie die betreffende Person mit <strong>Für Meldung BAN-Portal</strong> kennzeichnen. Das <strong>BAN-Portal</strong> ist das Belegungs-, Abrechnungs- und Nachweisportal im Übergang von der Schule in den Beruf. Das Vorgehen erläutert <a href="/schild3/import-export-statistik/export-fuer-ban-portal-verwaltung-export.html">Schülerdaten für das BAN-Portal vorbereiten und exportieren</a>.</p><p>Ebenso lassen sich hier die beiden <strong>Förderschwerpunkte</strong> erfassen. Achten Sie bitte auf eine statistikkonforme Eintragung.</p><p>Unten in diesem Detailblock werden die beiden <strong>Lernbereichsnoten</strong> zu <em>Gesellschaftswissenschaften</em> und <em>Naturwissenschaften</em> erfasst.</p><p>Sofern ein <strong>Bilingualer Zweig</strong> vorliegt, wird dieser im entsprechenden Feld vermerkt.</p>',11),e("div",{"data-hint-kind":"caution",class:"danger custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"caution","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m10.3 4-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"}),e("path",{d:"M12 9v4m0 4v.1"})]),n("Achtung")]),e("p",null,"Alle mit einem Sternchen gekennzeichneten Felder sind statistikrelevant.")],-1),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,[n("Sollten bei diesen Feldern bei mehreren Lernenden Änderungen nötig werden, können die Änderungen komfortabel über "),e("em",null,"Gruppenprozesse"),n(" durchgeführt werden.")])],-1),r('<h4 id="fehlstunden" tabindex="-1">Fehlstunden <a class="header-anchor" href="#fehlstunden" aria-label="Permalink to &quot;Fehlstunden&quot;">​</a></h4><p>Die Fehlstunden werden über die gesamten Fehlstunden (<strong>Ges.Fehlsdt.</strong>) und die unentschuldigten Fehlstunden (<strong>Unentschuldigt</strong>) erfasst. Diese können auch per <em>Gruppenprozess</em> gesetzt werden. Die Notenerfassung mit GradeHub und WeNoM ist dem SVWS-Server zugeordnet. Einrichtung und Bedienung sind in der <a href="https://doku.svws-nrw.de/" target="_blank" rel="noreferrer">SVWS-Dokumentation</a> beschrieben; siehe auch <a href="/zeugnisse/noteneingabe.html">Noten mit GradeHub und WeNoM erfassen</a>.</p><p>Wurde das Feld <strong>Max. Fehlstd.</strong> gefüllt, dies ist auch über einen <em>Gruppenprozess</em> möglich, werden bei einer Überschreitung die <strong>Ges.Fehlstd.</strong> fett markiert.</p><p>Weitere Informationen zu Fehlzeiten, der Konfiguration und der Erfassung von Fehlzeiten findet sich im Artikel über die <a href="/schild3/schueler/fehlzeiten-aktuelles-halbjahr-aktueller-abschnitt.html">Fehlzeiten tagesbezogen erfassen und auswerten</a>.</p><h3 id="allgemeine-angaben-ii" tabindex="-1">Allgemeine Angaben II <a class="header-anchor" href="#allgemeine-angaben-ii" aria-label="Permalink to &quot;Allgemeine Angaben II&quot;">​</a></h3><p><a href="/bilder/schueler/akt-halbj-allgemeine-angaben-ii.png"><img src="'+d+'" alt="An BKs finden sich hier auch die Allgemeinen Angaben II." loading="lazy"></a></p><p><em>An BKs finden sich hier auch die Allgemeinen Angaben II.</em></p><p>An Berufskollegs finde sich hier das Feld <em>Allgemeine Angaben II</em> zur <strong>Fachklasse</strong> und dem Berufsabschluss.</p><p>Liegt ein <strong>Schwerpunkt</strong> des Bildungsganges vor, wird dieser hier eingetragen. Die Schwerpunkte werden über <em>Kataloge ➜ Schwerpunkt</em> definiert.</p><h3 id="vor-und-rucktritt-im-schuljahr" tabindex="-1">Vor- und Rücktritt im Schuljahr <a class="header-anchor" href="#vor-und-rucktritt-im-schuljahr" aria-label="Permalink to &quot;Vor- und Rücktritt im Schuljahr&quot;">​</a></h3><p><a href="/bilder/schueler/akt-halbj-allgemein-7.png"><img src="'+u+'" alt="Vor- und Rücktritte im laufenden Schuljahr werden nicht über die Individualdaten I durchgeführt!" loading="lazy"></a></p><p><em>Vor- und Rücktritte im laufenden Schuljahr werden <strong>nicht</strong> über die Individualdaten I durchgeführt!</em></p><p>Um einen Vor- oder Rücktritt im laufenden Schuljahr bei einem Lernenden durchzuführen, darf der aktuelle Lernabschnitt nicht einfach in den Individualdaten I verändert werden.</p><p>Die betreffende Person wurde zum Schuljahreswechsel gültig in eine Klasse versetzt - oder eben nicht versetzt - und ein Wechsel im laufenden Schuljahr muss somit auch in der Laufbahn vermerkt werden.</p><p><a href="/bilder/schueler/akt-halbj-allgemein-2.png"><img src="'+o+'" alt="Vor- und Rücktritt im laufenden Schuljahr." loading="lazy"></a></p><p><em>Vor- und Rücktritt im laufenden Schuljahr.</em></p><p>Im Reiter &quot;Schüler&quot; ➜ &quot;Akt. Halbjahr&quot; gibt es oberhalb der Liste mit den Lernabschnitten zwei Schaltflächen um einen freiwilligen Rückgang beziehungsweise eine Vorversetzung durchzuführen.</p><p>Klicken Sie auf die nach links weisende Hand <strong>Rücktritt im laufenden Schuljahr</strong>. Wählen Sie im folgenden Fenster die neue Klasse im vorherigen Jahrgang und bestätigen Sie mit <strong>OK</strong>.</p><p>Analog wird bei <em>&quot;Sprung nach oben im laufenden Schuljahr&quot;</em> mit der nach rechts weisenden Hand vorgegangen. Auch hier ist wieder die neue Klasse zu wählen.</p><p>Nachdem der Lernende im Hauptfenster von SchILD einmal ab und neu angewählt wurde, sollte die neue Klasse beim unter <em>&quot;Laufbahn&quot;</em> im Reiter <em>Individualdaten I</em> geprüft werden. Prüfen Sie auch den korrekten <em>&quot;Statistik-Jahrgang&quot;</em>.</p><p><a href="/bilder/schueler/akt-halbj-allgemein-3.png"><img src="'+c+'" alt="Die Abschnittsübersicht nach dem Wechseln." loading="lazy"></a></p><p><em>Die Abschnittsübersicht nach dem Wechseln.</em></p><p>Es ist in der Laufbahn bei den Lernabschnitten zu sehen, dass ein neuer Lernabschnitt angelegt wurde und es zum aktuellen Abschnitt zwei Einträge gibt, wobei der ältere der beiden mit <em>&quot;(vor dem Wechsel)&quot;</em> gekennzeichnet ist.</p>',23),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,"Es sollten nun aktuelle Klassenlisten herausgegeben werden. Denken Sie ebenfalls daran, ein aktuelles Stammblatt zu hinterlegen.")],-1),r('<p><a href="/bilder/schueler/akt-halbj-allgemein-9.png"><img src="'+g+'" alt="Der Schülerfilter erlaubt das filtern auf Rücktritte im laufenden Schuljahr. Der Schülerfilter wird hier im Screenshot noch als &quot;Filter I&quot; angezeigt." loading="lazy"></a></p><p><em>Der Schülerfilter erlaubt das filtern auf Rücktritte im laufenden Schuljahr. Der Schülerfilter wird hier im Screenshot noch als &quot;Filter I&quot; angezeigt.</em></p><p>Über den <em>Schülerfilter</em> lassen sich Rücktritte im laufenden Schuljahr finden.</p><h3 id="zeugnis-abschluss" tabindex="-1">Zeugnis/Abschluss <a class="header-anchor" href="#zeugnis-abschluss" aria-label="Permalink to &quot;Zeugnis/Abschluss&quot;">​</a></h3><p><a href="/bilder/schueler/akt-halbj-allgemein-8.png"><img src="'+b+'" alt="Angaben zu Zeugnis und Abschluss." loading="lazy"></a></p><p><em>Angaben zu Zeugnis und Abschluss.</em></p><p>Unterhalb der allgemeinen Angaben finden sich die Informationen, die bei einem Lernabschnitt zu Zeugnis, Versetzung und eventuellem Abschluss gesetzt wurden.</p><p>Alle Eintragungen können hier oder unter dem Reiter <em>Leistungsdaten</em> manuell vorgenommen werden. Der größte Teil der Eintragungen wird jedoch per Gruppenprozess für komplette Jahrgänge vorgenommen. So lassen sich per Gruppenprozess die Daten setzen oder eine automatische Versetzungs- und Abschlussprüfung durchführen.</p>',8),e("div",{"data-hint-kind":"important",class:"warning custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"important","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 7v6m0 4v.1"})]),n("Wichtig")]),e("p",null,"Die Schule ist für die Angaben zu Versetzung und Abschluss verantwortlich. Maßgeblich sind die erbrachten Leistungen, die geltenden Bestimmungen und der Beschluss der Zeugniskonferenz. Die automatische Prüfung unterstützt diese Entscheidung; sie ersetzt die fachliche Prüfung nicht.")],-1),r("<p>Zumindest werden ein <strong>Konferenzdatum</strong> und ein <strong>Zeugnisdatum</strong> eingetragen.</p><p>Beim <strong>Versetzungsvermerk</strong> können die folgenden Einträge gewählt werden:</p><ul><li><em>Versetzt</em></li><li><em>Vorversetzt</em></li><li><em>Freiwillig zurück</em></li><li><em>Nicht versetzt</em></li><li><em>N.v., Nachprüfung möglich</em>: hier wird SchILD die Fächer ausweisen, für die dem Algorithmus eine Nachprüfung möglich erscheint.</li><li><em>Abschluss&quot;</em></li></ul><p>Tragen Sie bei Bedarf die <strong>Abschluss-Art</strong> des Jahrgangs und darunter den konkret erreichten <strong>Abschluss</strong> ein. Die <strong>Folgeklasse</strong> ergibt sich aus der Versetzungstabelle. In Jahrgängen, die die Schullaufbahn beenden, etwa nach dem Abitur in der Q2, bleibt sie leer.</p><p>Der Jahrgang wie auch der eventuell erreichte Abschluss bestimmen die <strong>Zeugnisart</strong>.</p>",5),e("div",{"data-hint-kind":"example",class:"example custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"example","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 3h6m-5 0v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3M7 15h10"})]),n("Beispiel")]),e("p",null,[n("Hier wäre etwa bei einem Lernenden, der im laufenden Schuljahr die Schule wechselt ein "),e("em",null,"Überweisungszeugnis"),n(" einzutragen.")])],-1),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Achten Sie bei Abgangs- und Abschlusszeugnissen darauf, auch die "),e("em",null,"Sprachenfolge"),n(" überprüft und korrekt gesetzt/berechnet zu haben.**")])],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Aktuelles_Halbjahr_/_Aktueller_Abschnitt_(Sch%C3%BCler)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 5662.")],-1)])])}const v=i(m,[["render",p]]);export{z as __pageData,v as default};
